export function findDeviceByName(searchName: string): DeviceProfile | null {
  const normalizedSearch = searchName.toLowerCase().trim()

  for (const device of deviceDatabase) {
    if (device.name.toLowerCase() === normalizedSearch) {
      return device
    }

    for (const alias of device.alias) {
      if (alias.toLowerCase() === normalizedSearch) {
        return device
      }
    }
  }

  return null
}

export function findDeviceById(deviceId: string): DeviceProfile | null {
  return deviceDatabase.find((device) => device.id === deviceId) ?? null
}

export function getAllDevices(): DeviceProfile[] {
  return deviceDatabase
}
